def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    for dc in (-1, 1):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                # Only process the first cell of each diagonal run.
                pr, pc = r - 1, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += 1
                    cc += dc
                if len(cells) < 2:
                    continue

                ends = [
                    (cells[0][0], cells[0][1], -1, -dc),
                    (cells[-1][0], cells[-1][1], 1, dc),
                ]
                candidates = []
                for er, ec, dr, dcol in ends:
                    # Extend from an exposed endpoint, not one attached
                    # orthogonally to another colored part of the figure.
                    exposed = True
                    for ar, ac in ((er-1, ec), (er+1, ec), (er, ec-1), (er, ec+1)):
                        if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg:
                            exposed = False
                            break
                    if not exposed:
                        continue

                    ray = []
                    ar, ac = er + dr, ec + dcol
                    while 0 <= ar < h and 0 <= ac < w and grid[ar][ac] == bg:
                        ray.append((ar, ac))
                        ar += dr
                        ac += dcol
                    if ray:
                        candidates.append((len(ray), ray))

                if candidates:
                    _, ray = max(candidates, key=lambda x: x[0])
                    for ar, ac in ray:
                        out[ar][ac] = color

    return out
